-- A row that does not fit into a page is stored in a chain of overflow
-- pages.  A chain of more than one page has to be read back completely, the
-- content is compared instead of printed to keep the expected file small.
CREATE TABLE t (id BIGINT PRIMARY KEY, content VARCHAR(16384), v VECTOR(4));
INSERT INTO t VALUES (1, '', '[1, 0, 0, 0]');
INSERT INTO t VALUES (2, '', '[0, 1, 0, 0]');
INSERT INTO t VALUES (3, '', '[0, 0, 1, 0]');
SELECT id FROM t ORDER BY id;
SELECT id FROM t WHERE content = '';
SELECT id FROM t WHERE content = '';
SELECT id FROM t WHERE content <> '' ORDER BY id;
SELECT id, L2_DISTANCE(v, '[1, 0, 0, 0]') AS d FROM t ORDER BY d;
UPDATE t SET content = '' WHERE id = 3;
SELECT id FROM t WHERE content = '';
DELETE FROM t WHERE id = 1;
SELECT id FROM t ORDER BY id;
